81	// Resolve the CTA label based on current plan vs tier
82	function getCtaLabel(
83	  tierPlan: PlanType,
84	  currentPlan: PlanType | null,
85	  defaultLabel: string
86	): string {
87	  if (!currentPlan) return defaultLabel;
88	  if (currentPlan === tierPlan) return "Current Plan";
89	  if (tierPlan === "free") return "Downgrade to Free";
90	
91	  const planOrder: PlanType[] = ["free", "starter", "growth", "pro", "agency"];
92	  const currentIndex = planOrder.indexOf(currentPlan);
93	  const tierIndex = planOrder.indexOf(tierPlan);
94	
95	  if (tierIndex > currentIndex) return `Upgrade to ${PLAN_NAMES[tierPlan]}`;
96	  return `Switch to ${PLAN_NAMES[tierPlan]}`;
97	}
