99	const Pricing = () => {
100	  const [isAnnual, setIsAnnual] = useState(false);
101	  const navigate = useNavigate();
102	  const { profile } = useAuth();
103	  const checkout = useCheckout();
104	  const portal = useCustomerPortal();
105	
106	  const currentPlan = profile?.plan ?? null;
107	  const billingCycle = isAnnual ? "annual" : "monthly";
108	
109	  function handleCta(tierPlan: PlanType) {
110	    if (!profile) {
111	      // Not logged in — send to signup
112	      navigate("/auth");
113	      return;
114	    }
115	
116	    if (tierPlan === "free" || tierPlan === currentPlan) {
