145	            <Switch id="billing-toggle" checked={isAnnual} onCheckedChange={setIsAnnual} />
146	            <Label htmlFor="billing-toggle" className={cn("text-sm", isAnnual && "font-semibold text-foreground")}>
147	              Annual
148	            </Label>
149	            {isAnnual && (
150	              <Badge className="bg-green-50 text-green-700 border-green-200 text-xs">
151	                Save 20%
152	              </Badge>
153	            )}
154	          </div>
155	        </div>
156	
157	        {/* Pricing Cards */}
158	        <div className="mx-auto grid max-w-5xl grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-4">
159	          {PRICING_TIERS.map((tier) => {
