161	            const isCurrentPlan = currentPlan === tier.plan;
162	            const isPaidPlan = tier.plan !== "free";
163	            const isCheckoutPending =
164	              checkout.isPending &&
165	              checkout.variables?.plan === tier.plan;
166	            const isPortalPending =
167	              portal.isPending &&
168	              (isCurrentPlan || tier.plan === "free");
169	
170	            const ctaLabel = profile
171	              ? getCtaLabel(tier.plan, currentPlan, tier.cta_text)
172	              : tier.cta_text;
173	
174	            const isPending = isCheckoutPending || isPortalPending;
175	
176	            return (
177	              <Card
178	                key={tier.plan}
179	                className={cn(
180	                  "relative border-border/40 shadow-soft hover:shadow-soft-lg hover:-translate-y-1 transition-all duration-300",
181	                  tier.highlighted &&
182	                    "border-primary ring-2 ring-primary/20 sm:scale-[1.02] shadow-lg shadow-primary/10"
183	                )}
184	              >
185	                {tier.highlighted && (
186	                  <div className="absolute -top-3 left-1/2 -translate-x-1/2">
187	                    <Badge className="bg-primary text-primary-foreground px-3 py-1 text-xs font-semibold">
188	                      <Zap className="mr-1 h-3 w-3" />
189	                      Most Popular
190	                    </Badge>
191	                  </div>
192	                )}
193	                {isCurrentPlan && (
194	                  <div className="absolute -top-3 left-1/2 -translate-x-1/2">
195	                    <Badge variant="outline" className="bg-card px-3 py-1 text-xs font-semibold border-border">
