200	                <CardHeader className="text-center pb-2 pt-8">
201	                  <CardTitle className={cn("text-lg font-semibold", tier.highlighted ? "text-primary" : "text-foreground")}>
202	                    {tier.name}
203	                  </CardTitle>
204	                  <CardDescription className="text-sm">{tier.subtitle}</CardDescription>
205	                </CardHeader>
206	                <CardContent className="text-center">
207	                  <div className="mb-1">
208	                    <span className="text-4xl font-semibold leading-none text-foreground tabular-nums">
