229	                      ) : (
230	                        "Manage Subscription"
231	                      )}
232	                    </Button>
233	                  ) : (
234	                    <Button
235	                      className={cn("w-full rounded-lg", !tier.highlighted && "bg-card border border-border/50 text-foreground hover:bg-muted/50")}
236	                      variant={tier.highlighted ? "default" : "outline"}
237	                      disabled={isPending || isCurrentPlan}
238	                      onClick={() => handleCta(tier.plan)}
239	                    >
240	                      {isPending ? (
241	                        <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Redirecting...</>
242	                      ) : (
243	                        ctaLabel
244	                      )}
245	                    </Button>
246	                  )}
247	
248	                  <ul className="mt-6 space-y-3 text-left">
249	                    <TooltipProvider delayDuration={300}>
250	                      {tier.features.map((feature, i) => (
251	                        <li key={i} className="flex items-start gap-2.5">
252	                          {feature.included ? (
253	                            <Check className="mt-0.5 h-4 w-4 shrink-0 text-green-500" />
254	                          ) : (
255	                            <X className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground/40" />
256	                          )}
257	                          <span className={cn("text-sm", feature.included ? "text-foreground" : "text-muted-foreground")}>
258	                            {feature.text}
259	                          </span>
260	                          {feature.tooltip && (
261	                            <Tooltip>
262	                              <TooltipTrigger asChild>
263	                                <HelpCircle className="mt-0.5 h-3.5 w-3.5 shrink-0 text-muted-foreground/40 cursor-help" />
264	                              </TooltipTrigger>
265	                              <TooltipContent side="top"><p className="text-xs">{feature.tooltip}</p></TooltipContent>
266	                            </Tooltip>
267	                          )}
268	                        </li>
269	                      ))}
270	                    </TooltipProvider>
271	                  </ul>
272	                </CardContent>
273	              </Card>
274	            );
275	          })}
276	        </div>
277	
278	        {/* Trust badges */}
279	        <div className="flex flex-wrap items-center justify-center gap-6 text-xs text-muted-foreground">
280	          {[
281	            { icon: Shield, text: "256-bit SSL encrypted" },
282	            { icon: Shield, text: "SOC 2 compliant infrastructure" },
283	            { icon: Shield, text: "GDPR compliant" },
284	            { icon: Shield, text: "30-day money-back guarantee" },
285	          ].map((badge) => (
286	            <span key={badge.text} className="flex items-center gap-1.5">
287	              <badge.icon className="h-3.5 w-3.5 text-muted-foreground" />
288	              {badge.text}
289	            </span>
290	          ))}
291	        </div>
292	
293	        <Separator />
294	
295	        {/* Feature Comparison Table */}
296	        <div className="mx-auto max-w-4xl">
297	          <h3 className="mb-6 text-center text-xl font-bold text-foreground">Feature comparison</h3>
298	          <div className="overflow-x-auto">
299	            <table className="w-full min-w-[700px] text-sm">
300	              <thead>
301	                <tr className="border-b border-border/50">
302	                  <th className="pb-3 text-left font-medium text-muted-foreground">Feature</th>
303	                  <th className="pb-3 text-center font-medium text-muted-foreground w-24">Starter</th>
304	                  <th className="pb-3 text-center font-semibold text-primary w-24">Growth</th>
305	                  <th className="pb-3 text-center font-medium text-muted-foreground w-24">Pro</th>
306	                  <th className="pb-3 text-center font-medium text-muted-foreground w-24">Agency</th>
307	                </tr>
308	              </thead>
309	              <tbody>
310	                {COMPARISON_ROWS.map((row) => (
311	                  <tr key={row.feature} className="border-b border-border/40">
312	                    <td className="py-3 text-foreground">{row.feature}</td>
313	                    {[row.starter, row.growth, row.pro, row.agency].map((val, i) => (
314	                      <td key={i} className="py-3 text-center">
315	                        {val === true ? (
316	                          <Check className="mx-auto h-4 w-4 text-green-500" />
